package com.example.editor.textual.source;
public record TextualModelSourceDocument(String id,String relativePath,String content,long revision){public TextualModelSourceDocument{id=text(id);relativePath=text(relativePath).replace('\\','/');content=content==null?"":content;revision=Math.max(0,revision);if(relativePath.startsWith("/")||relativePath.contains("../"))throw new IllegalArgumentException("Textual model path must be relative and portable");}/** Descripción: Ejecuta la operación «text» correspondiente a la responsabilidad de TextualModelSourceDocument. Entradas: v: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String text(String v){return v==null?"":v.trim();}}
